// План specs/billing.md 2.1 / 2.2 (#feb50f). Pre-Prod (Stripe test mode), десктоп, EN. Оплата НЕ выполняется.
// Stripe Checkout открывается в USD ($1.00 по Payment Link работы, $49.00/мес за доп. компанию), без авто-конвертации в ILS
// (было ₪3.30 и ₪161.97). Окно клиента — с локалью he-IL (конфиг проекта) и часовым поясом Израиля, чтобы Adaptive Pricing сработал, если он включён.
// 2.1 — @writes @data @stripe-test: работа «QA-AUTO pay …» с позицией $1 + Payment Link; в конце ссылка отменяется, работа → Cancelled.
// 2.2 — аккаунт preprod-a (без активной доп. компании): Billing → Add another company → Add for $49/mo → Checkout; если кнопки нет — пропуск.
// Пункт «prod live Stripe» — только человек (live-режим), в автотест не входит.
// Не сверено с сайтом при записи: кнопка «Pay $1.00» на /pay перенаправляет на checkout.stripe.com; подписи Checkout (сумма в тексте страницы).
import { test, expect } from '../../fixtures';
import {
  blockMessaging, cancelJob, cancelOpenLinks, createJobWithBalance, createPaymentLink, expectPayPage, jobNumber,
  openCustomerContext, openPaymentsTab,
} from '../job-payments/payments-helpers';
import { openBilling, pp } from './billing-helpers';

test.describe('Stripe Checkout currency (#feb50f)', () => {
  test('QA-AUTO: Payment Link $1 → Stripe Checkout shows $1.00 and no ₪, no currency switcher #feb50f @desktop @writes @data @stripe-test', async ({ asUser, browser }, testInfo) => {
    test.setTimeout(180_000);
    const page = await asUser('preprod-ttp');
    const messaging = await blockMessaging(page);
    const customer = await openCustomerContext(browser, testInfo);
    let jobUrl: string | null = null;
    try {
      jobUrl = await createJobWithBalance(page, 'currency', { price: '1', ticket: '#feb50f' });
      await openPaymentsTab(page, jobUrl);
      const jobNo = await jobNumber(page);
      const link = await createPaymentLink(page);

      await customer.page.goto(link);
      await expectPayPage(customer.page, '$1.00', jobNo);
      await customer.page.getByRole('button', { name: 'Pay $1.00' }).click();
      await customer.page.waitForURL(/checkout\.stripe\.com/, { timeout: 30_000 });

      const body = customer.page.locator('body');
      await expect(body).toContainText('$1.00', { timeout: 30_000 });
      await expect(body, 'нет авто-конвертации в шекели').not.toContainText('₪');
      await expect(customer.page.getByText(/ILS|Israeli/i)).toHaveCount(0);
      expect(messaging, 'SMS/email не отправлялись').toEqual([]);
    } finally {
      await customer.context.close();
      await cancelOpenLinks(page, jobUrl);
      await cancelJob(page, jobUrl);
    }
  });

  test('Add another company → Add for $49/mo opens Checkout in USD ($49.00/month, no ₪); leave without paying #feb50f @desktop @stripe-test', async ({ asUser }) => {
    test.setTimeout(120_000);
    const page = await asUser('preprod-a');
    await openBilling(page);
    const add = page.getByRole('button', { name: /Add another company/i }).first();
    test.skip(!(await add.isVisible()), 'у аккаунта preprod-a нет кнопки Add another company (доп. компания уже куплена)');
    await add.click();
    await page.getByRole('button', { name: /Add for \$49/ }).click();
    await page.waitForURL(/checkout\.stripe\.com/, { timeout: 30_000 });
    await expect(page.locator('body')).toContainText('$49.00', { timeout: 30_000 });
    await expect(page.locator('body'), 'нет ₪').not.toContainText('₪');
    // Выход без оплаты: «Checkout cancelled / Nothing was charged» (#1649c3)
    await page.goBack();
    await page.waitForURL((u) => !/checkout\.stripe\.com/.test(u.toString()), { timeout: 30_000 });
  });
});
